package org.example.server.persistence.repository;
import jakarta.persistence.LockModeType;import org.example.server.persistence.entity.PurchaseHeaderEntity;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Lock;import org.springframework.data.jpa.repository.Query;import org.springframework.data.repository.query.Param;import org.springframework.data.domain.Pageable;import java.util.*;
public interface PurchaseHeaderRepository extends JpaRepository<PurchaseHeaderEntity,Integer>{Optional<PurchaseHeaderEntity> findByInvoiceNo(String invoiceNo);@Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select purchase from PurchaseHeaderEntity purchase where purchase.invoiceNo=:invoiceNo") Optional<PurchaseHeaderEntity> findByInvoiceNoForUpdate(@Param("invoiceNo") String invoiceNo);@Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select purchase from PurchaseHeaderEntity purchase where purchase.id=:id") Optional<PurchaseHeaderEntity> findByIdForUpdate(@Param("id") Integer id); boolean existsByInvoiceNo(String invoiceNo); List<PurchaseHeaderEntity> findAllByOrderByInvoiceDateDescIdDesc(); @Query("select purchase from PurchaseHeaderEntity purchase where (coalesce(purchase.totalAmount,0)-coalesce(purchase.paidAmount,0)) > 0.009 and upper(coalesce(purchase.documentStatus,'')) not in ('CANCELLED','DELETED','DRAFT','RETURNED') order by abs((coalesce(purchase.totalAmount,0)-coalesce(purchase.paidAmount,0)) - :amount) asc, purchase.invoiceDate desc, purchase.id desc")  List<PurchaseHeaderEntity> findOpenForBankMatching(@Param("amount") double amount, Pageable pageable);}
